        # For this solution, we assume velocity is acceptable if descending
        # Check angle
        if abs(angle) > math.radians(7):
            sandbox.apply_thrust(0, 120.0)
        else:
            # Calculate platform position at touchdown
            time_at_land = step_count * (1/60)
            platform_x_at_land = 17.0 + 1.8 * math.sin((math.pi / 3) * time_at_land)
            platform_valid_x = [platform_x_at_land - 1.5, platform_x_at_land + 1.5]
            # Check if landing area is within valid zone
            if x >= platform_valid_x[0] and x <= platform_valid_x[1]:
                # Success
                return
            else:
                # Adjust thrust to align with platform
                delta_x = platform_x_at_land - x
                if delta_x > 0:
                    sandbox.apply_thrust(0, 120.0)
                else:
                    sandbox.apply_thrust(0, -120.0)
                sandbox.apply_thrust(-1200.0, 0)

    # Check fuel
    if fuel < 500.0:
        # Stop thrusting if fuel is low
        sandbox.apply_thrust(0, 0)
